16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.time.Period;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "title")
40	    private String title;
41	
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "address_line1")
47	    private String addressLine1;
48	
49	    @Column(name = "address_line2")
50	    private String addressLine2;
51	
52	    @Column(name = "city")
53	    @NotEmpty
54	    private String city;
55	
56	    @Column(name = "telephone")
57	    @NotEmpty
58	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 format")
59	    private String telephone;
60	
61	    @Column(name = "email")
62	    private String email;
63	
64	    @Column(name = "postcode")
65	    private String postcode;
66	
67	    @Column(name = "registration_date")
68	    private LocalDate registrationDate;
69	
70	    @Column(name = "birth_date")
71	    private LocalDate birthDate;
72	
73	    @Column(name = "customer_code")
74	    private String customerCode;
75	
76	    @Column(name = "household_id")
77	    private String householdId;
78	
79	    @Column(name = "namesake_count")
80	    private Integer namesakeCount;
81	
82	    @Column(name = "household_size")
83	    private Integer householdSize;
84	
85	    @Column(name = "membership_level_cap")
86	    private Integer membershipLevelCap;
87	
88	    @Column(name = "possible_duplicate")
89	    private Boolean possibleDuplicate;
90	
91	    @Column(name = "possible_duplicate_of")
92	    private Integer possibleDuplicateOf;
93	
94	    @Column(name = "deleted", nullable = false)
95	    private boolean deleted = false;
96	
97	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
98	    private Set<Pet> pets;
99	
100	    public String getTitle() {
101	        return this.title;
102	    }
103	
104	    public void setTitle(String title) {
105	        this.title = title;
106	    }
107	
108	    /**
109	     * The owner's salutation: the {@link #getTitle() title} followed by a space and the last name
110	     * (e.g. {@code "DR Franklin"}) when a title is present, or just the last name when no title has
111	     * been supplied.
112	     */
113	    public String getSalutation() {
114	        if (this.title == null || this.title.isEmpty()) {
115	            return this.getLastName();
116	        }
117	        return this.title + " " + this.getLastName();
118	    }
119	
120	    public String getAddress() {
121	        return this.address;
122	    }
123	
124	    public void setAddress(String address) {
125	        this.address = address;
126	    }
127	
128	    public String getAddressLine1() {
129	        return this.addressLine1;
130	    }
131	
132	    public void setAddressLine1(String addressLine1) {
133	        this.addressLine1 = addressLine1;
134	    }
135	
136	    public String getAddressLine2() {
137	        return this.addressLine2;
138	    }
139	
140	    public void setAddressLine2(String addressLine2) {
141	        this.addressLine2 = addressLine2;
142	    }
143	
144	    public String getCity() {
145	        return this.city;
146	    }
147	
148	    public void setCity(String city) {
149	        this.city = city;
150	    }
151	
152	    public String getTelephone() {
153	        return this.telephone;
154	    }
155	
156	    public void setTelephone(String telephone) {
157	        this.telephone = telephone;
158	    }
159	
160	    /**
161	     * The owner's stored E.164 {@link #getTelephone() telephone} formatted for humans: the country
162	     * code, a space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}).
163	     * The raw {@link #getTelephone() telephone} stays in E.164 form. Absent until a telephone has
164	     * been set.
165	     */
166	    public String getTelephoneDisplay() {
167	        return Telephone.forDisplay(this.telephone);
168	    }
169	
170	    public String getEmail() {
171	        return this.email;
172	    }
173	
174	    public void setEmail(String email) {
175	        this.email = email;
176	    }
177	
178	    public String getPostcode() {
179	        return this.postcode;
180	    }
181	
182	    public void setPostcode(String postcode) {
183	        this.postcode = postcode;
184	    }
185	
186	    public LocalDate getRegistrationDate() {
187	        return this.registrationDate;
188	    }
189	
190	    public void setRegistrationDate(LocalDate registrationDate) {
191	        this.registrationDate = registrationDate;
192	    }
193	
194	    public LocalDate getBirthDate() {
195	        return this.birthDate;
196	    }
197	
198	    public void setBirthDate(LocalDate birthDate) {
199	        this.birthDate = birthDate;
200	    }
201	
202	    public String getCustomerCode() {
203	        return this.customerCode;
204	    }
205	
206	    public void setCustomerCode(String customerCode) {
207	        this.customerCode = customerCode;
208	    }
209	
210	    /**
211	     * The owner's current primary identifier: the single external identifier by which this owner is
212	     * known. Today this is the {@link #getCustomerCode() customer code}; if a different identifier
213	     * later becomes primary (e.g. once the customer code is unified into a member id), this method
214	     * changes to return that instead, and every consumer that records the primary identifier follows
215	     * automatically.
216	     */
217	    public String getPrimaryIdentifier() {
218	        return getCustomerCode();
219	    }
220	
221	    public String getHouseholdId() {
222	        return this.householdId;
223	    }
224	
225	    public void setHouseholdId(String householdId) {
226	        this.householdId = householdId;
227	    }
228	
229	    public Integer getNamesakeCount() {
230	        return this.namesakeCount;
231	    }
232	
233	    public void setNamesakeCount(Integer namesakeCount) {
234	        this.namesakeCount = namesakeCount;
235	    }
236	
237	    public Integer getHouseholdSize() {
238	        return this.householdSize;
239	    }
240	
241	    public void setHouseholdSize(Integer householdSize) {
242	        this.householdSize = householdSize;
243	    }
244	
245	    /**
246	     * The ceiling applied to this owner's {@link #getMembershipLevel() membership level}: one above
247	     * the highest membership level held by the owner's household members when this owner was created.
248	     * {@code null} when the owner had no existing household member and so is uncapped.
249	     */
250	    public Integer getMembershipLevelCap() {
251	        return this.membershipLevelCap;
252	    }
253	
254	    public void setMembershipLevelCap(Integer membershipLevelCap) {
255	        this.membershipLevelCap = membershipLevelCap;
256	    }
257	
258	    /**
259	     * Whether this owner, though not a hard duplicate, matches an existing owner's last name by
260	     * Soundex and shares its postcode while holding a different identity key. Resolved at creation
261	     * and stored so it is reported consistently on every later read.
262	     */
263	    public Boolean getPossibleDuplicate() {
264	        return this.possibleDuplicate;
265	    }
266	
267	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
268	        this.possibleDuplicate = possibleDuplicate;
269	    }
270	
271	    /**
272	     * The id of the existing owner this owner is a possible duplicate of, or {@code null} when it
273	     * is not a possible duplicate.
274	     */
275	    public Integer getPossibleDuplicateOf() {
276	        return this.possibleDuplicateOf;
277	    }
278	
279	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
280	        this.possibleDuplicateOf = possibleDuplicateOf;
281	    }
282	
283	    /**
284	     * Whether this owner has been soft-deleted. A soft-deleted owner keeps its row and remains
285	     * retrievable, but is ignored by the create endpoint's duplicate and identity checks. A newly
286	     * created owner is never deleted.
287	     */
288	    public boolean isDeleted() {
289	        return this.deleted;
290	    }
291	
292	    public void setDeleted(boolean deleted) {
293	        this.deleted = deleted;
294	    }
295	
296	    /**
297	     * The owner's identity key: the single derived value used to detect duplicate owners, formed as
298	     * the SHA-256 hex digest of {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}
299	     * where an absent telephone or email contributes an empty string. Because the telephone is part
300	     * of the key, housemates that share a last name and postcode but hold different telephones have
301	     * distinct identity keys and are both allowed (and merely flagged as possible duplicates).
302	     */
303	    public String getIdentityKey() {
304	        String key = orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + Soundex.of(this.getLastName());
305	        return Sha256.hex(key);
306	    }
307	
308	    private static String orEmpty(String value) {
309	        return value == null ? "" : value;
310	    }
311	
312	    /**
313	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
314	     * last two digits of the {@link #getFiscalYear() fiscal year} of the business-day-adjusted
315	     * registration date (e.g. {@code 'SMI-0007-M27'}). Derived from the owner's own fields;
316	     * absent until both the customer code and registration date have been assigned.
317	     */
318	    public String getMembershipNumber() {
319	        if (this.customerCode == null || this.registrationDate == null) {
320	            return null;
321	        }
322	        return String.format("%s-M%02d", this.customerCode, FiscalYear.endingYear(this.registrationDate) % 100);
323	    }
324	
325	    /**
326	     * The owner's fiscal year, formatted {@code 'FY<YY>'} and derived from the business-day-adjusted
327	     * {@link #getRegistrationDate() registration date}. The fiscal year starts on 1 July; see
328	     * {@link FiscalYear}. Absent until a registration date has been assigned.
329	     */
330	    public String getFiscalYear() {
331	        if (this.registrationDate == null) {
332	            return null;
333	        }
334	        return FiscalYear.label(this.registrationDate);
335	    }
336	
337	    /**
338	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of the
339	     * {@link #getCustomerCode() customer code}. Absent until the customer code has been assigned.
340	     */
341	    public Integer getCheckDigit() {
342	        if (this.customerCode == null) {
343	            return null;
344	        }
345	        return Luhn.checkDigit(this.customerCode);
346	    }
347	
348	    /**
349	     * The owner's tenure in whole elapsed fiscal years: the number of 1 July boundaries crossed
350	     * from the {@link #getRegistrationDate() registration date} up to today (see {@link FiscalYear}).
351	     * An owner still in their registration fiscal year has a tenure of zero. Absent until a
352	     * registration date is present.
353	     */
354	    public Long getTenureFiscalYears() {
355	        if (this.registrationDate == null) {
356	            return null;
357	        }
358	        return FiscalYear.elapsed(this.registrationDate, LocalDate.now());
359	    }
360	
361	    /**
362	     * The owner's membership points, a score derived from the owner's own fields: starting from 0,
363	     * the owner earns 2 points when an email address is present, 1 point when this owner has no
364	     * namesakes ({@code namesakeCount} is 0), 2 points for a household of 3 or more members, and 3
365	     * points once the owner's {@link #getTenureFiscalYears() tenure} spans at least one full fiscal
366	     * year (the registration and current dates fall in different fiscal years).
367	     */
368	    public Integer getMembershipPoints() {
369	        int points = 0;
370	        boolean hasEmail = this.email != null && !this.email.isEmpty();
371	        if (hasEmail) {
372	            points += 2;
373	        }
374	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
375	        if (unique) {
376	            points += 1;
377	        }
378	        boolean sharedHousehold = this.householdSize != null && this.householdSize >= 3;
379	        if (sharedHousehold) {
380	            points += 2;
381	        }
382	        Long tenureFiscalYears = getTenureFiscalYears();
383	        boolean tenured = tenureFiscalYears != null && tenureFiscalYears >= 1;
384	        if (tenured) {
385	            points += 3;
386	        }
387	        return points;
388	    }
389	
390	    /**
391	     * The owner's membership level, a number from 1 to 4 derived from the owner's
392	     * {@link #getMembershipPoints() membership points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and
393	     * 4 for 6 or more. The level is then held to its {@link #getMembershipLevelCap() cap} (one above
394	     * the highest level among the owner's household members at creation), so a new owner cannot rank
395	     * more than one level above their household. An uncapped owner keeps the derived level.
396	     */
397	    public Integer getMembershipLevel() {
398	        int level = derivedMembershipLevel();
399	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
400	            return this.membershipLevelCap;
401	        }
402	        return level;
403	    }
404	
405	    private int derivedMembershipLevel() {
406	        int points = getMembershipPoints();
407	        if (points >= 6) {
408	            return 4;
409	        }
410	        if (points >= 4) {
411	            return 3;
412	        }
413	        if (points >= 2) {
414	            return 2;
415	        }
416	        return 1;
417	    }
418	
419	    /**
420	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customer code} (the
421	     * region derived from the postcode when the identity was assigned), or {@link Regions#UNKNOWN}
422	     * before a customer code has been assigned.
423	     */
424	    public String getLocality() {
425	        if (this.customerCode == null) {
426	            return Regions.UNKNOWN;
427	        }
428	        int separator = this.customerCode.indexOf('-');
429	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
430	    }
431	
432	    /**
433	     * The owner's timezone: the IANA timezone name for the owner's {@link #getLocality() locality}
434	     * from the fixed region-to-timezone table (NSW&rarr;Australia/Sydney, VIC&rarr;Australia/Melbourne,
435	     * QLD&rarr;Australia/Brisbane), or absent when the locality has no known timezone.
436	     */
437	    public String getTimezone() {
438	        return Regions.timezoneOf(getLocality());
439	    }
440	
441	    /**
442	     * The owner's preferred contact channel, derived from the owner's own fields:
443	     * {@code "EMAIL"} when an {@link #getEmail() email} is present, otherwise {@code "PHONE"}.
444	     */
445	    public String getContactPreference() {
446	        boolean hasEmail = this.email != null && !this.email.isEmpty();
447	        return hasEmail ? "EMAIL" : "PHONE";
448	    }
449	
450	    /**
451	     * The owner's age band, derived from the owner's own fields: the whole years between
452	     * {@link #getBirthDate() birth date} and {@link #getRegistrationDate() registration date}
453	     * classified as {@code "MINOR"} (under 18), {@code "ADULT"} (18-64) or {@code "SENIOR"}
454	     * (65 or older). Absent until a birth date and a registration date are both present.
455	     */
456	    public String getAgeBand() {
457	        if (this.birthDate == null || this.registrationDate == null) {
458	            return null;
459	        }
460	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
461	        if (age < 18) {
462	            return "MINOR";
463	        }
464	        return age < 65 ? "ADULT" : "SENIOR";
465	    }
466	
467	    /**
468	     * Resolve the effective registration date before persisting: default it to the server's
469	     * current date when none was supplied, then roll it forward off weekends so a newly
470	     * registered owner always has a business-day registration date. Every value derived from it
471	     * (such as the {@link #getMembershipNumber() membership number}) therefore uses the adjusted
472	     * date.
473	     */
474	    @PrePersist
475	    private void resolveRegistrationDate() {
476	        if (this.registrationDate == null) {
477	            this.registrationDate = LocalDate.now();
478	        }
479	        this.registrationDate = BusinessDay.onOrAfter(this.registrationDate);
480	    }
481	
482	    /**
483	     * The owner's self link: the canonical API path of this owner, formatted
484	     * {@code "/api/owners/<id>"}. Absent until the owner has been assigned an id.
485	     */
486	    public String getSelfLink() {
487	        if (this.getId() == null) {
488	            return null;
