16	package org.springframework.samples.petclinic.model;
17	
18	import java.util.Map;
19	
20	/**
21	 * The fixed region lookup shared across the domain. It is the single source of truth for mapping an
22	 * owner to its canonical region: by postcode range first (NSW 2000&ndash;2099, VIC 3000&ndash;3099,
23	 * QLD 4000&ndash;4099) and, failing that, by the city-to-region table (Sydney&rarr;NSW,
24	 * Melbourne&rarr;VIC, Brisbane&rarr;QLD). Anything the tables do not cover resolves to
25	 * {@link #UNKNOWN}.
26	 */
27	public final class Regions {
28	
29	    /** The region assigned to any owner not resolved by the postcode or city tables. */
30	    public static final String UNKNOWN = "UNKNOWN";
31	
32	    private static final Map<String, String> CITY_REGIONS =
33	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
34	
35	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
36	    private static final Map<String, int[]> REGION_RANGES = Map.of(
37	        "NSW", new int[] {2000, 2099},
38	        "VIC", new int[] {3000, 3099},
39	        "QLD", new int[] {4000, 4099});
40	
41	    /** Region -&gt; IANA timezone name. */
42	    private static final Map<String, String> REGION_TIMEZONES = Map.of(
43	        "NSW", "Australia/Sydney",
44	        "VIC", "Australia/Melbourne",
45	        "QLD", "Australia/Brisbane");
46	
47	    private Regions() {
48	    }
49	
50	    /**
51	     * @param city the city to resolve
52	     * @return the canonical region for {@code city}, or {@link #UNKNOWN} when the city is not in the
53	     * fixed table
54	     */
55	    public static String regionOfCity(String city) {
56	        return CITY_REGIONS.getOrDefault(city, UNKNOWN);
57	    }
58	
59	    /**
60	     * @param postcode the postcode to resolve, may be {@code null} or blank
61	     * @return the region whose inclusive range contains {@code postcode}, or {@link #UNKNOWN} when
62	     * the postcode is absent, unparseable, or in no known range
63	     */
64	    public static String regionOfPostcode(String postcode) {
65	        Integer value = parse(postcode);
66	        if (value != null) {
67	            for (Map.Entry<String, int[]> entry : REGION_RANGES.entrySet()) {
68	                int[] range = entry.getValue();
69	                if (value >= range[0] && value <= range[1]) {
70	                    return entry.getKey();
71	                }
72	            }
73	        }
74	        return UNKNOWN;
75	    }
76	
77	    /**
78	     * @param region a canonical region
79	     * @return that region's inclusive {low, high} postcode range, or {@code null} when the region has
80	     * no known range
81	     */
82	    public static int[] rangeOf(String region) {
83	        return REGION_RANGES.get(region);
84	    }
85	
86	    /**
87	     * @param region a canonical region
88	     * @return that region's IANA timezone name, or {@code null} when the region has no known timezone
89	     */
90	    public static String timezoneOf(String region) {
91	        return REGION_TIMEZONES.get(region);
92	    }
93	
94	    private static Integer parse(String postcode) {
95	        if (postcode == null) {
96	            return null;
97	        }
98	        try {
99	            return Integer.parseInt(postcode.trim());
100	        } catch (NumberFormatException ex) {
101	            return null;
102	        }
103	    }
104	}
